import{_ as t,o as r,c as a,ak as o}from"./chunks/framework.sV-XtlWr.js";const g=JSON.parse('{"title":"Gap detectors & exposure","description":"Every Test Map detector with the class it reports, what it needs and its evidence, the exposure factors that rank gaps, and what the graph includes.","frontmatter":{"title":"Gap detectors & exposure","description":"Every Test Map detector with the class it reports, what it needs and its evidence, the exposure factors that rank gaps, and what the graph includes.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/reference/gap-detectors.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/reference/gap-detectors.html"}],["meta",{"property":"og:title","content":"Gap detectors & exposure | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Every Test Map detector with the class it reports, what it needs and its evidence, the exposure factors that rank gaps, and what the graph includes."}]]},"headers":[],"relativePath":"reference/gap-detectors.md","filePath":"reference/gap-detectors.md","lastUpdated":1791130662000}'),s={name:"reference/gap-detectors.md"};function d(n,e,i,c,h,l){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="gap-detectors-exposure" tabindex="-1">Gap detectors &amp; exposure <a class="header-anchor" href="#gap-detectors-exposure" aria-label="Permalink to &quot;Gap detectors &amp; exposure&quot;">​</a></h1><p>The <a href="/guide/concepts.html#detector">detectors</a> that turn the <a href="/features/scenario-gaps.html">Test Map</a> into scenario gaps, the <strong>exposure</strong> score that ranks them, and the rules that decide what the graph holds. Evidence counts use the last 30 runs of the project, probe runs excluded.</p><h2 id="detectors" tabindex="-1">Detectors <a class="header-anchor" href="#detectors" aria-label="Permalink to &quot;Detectors&quot;">​</a></h2><p>The Test Map is recomputed after every run, nightly, and on demand. Every detector reads the runs the <a href="/guide/capture-fixtures.html">capture fixtures</a> record; <strong>Needs</strong> names what else it reads, and a detector stays silent without it.</p><table tabindex="0"><thead><tr><th>Detector</th><th>Class</th><th>Finds</th><th>Needs</th><th>Example evidence</th></tr></thead><tbody><tr><td><strong>Success only</strong></td><td>blind-spot</td><td>a route observed at least five times, always with a 2xx or 3xx status: its error paths never ran</td><td>nothing more</td><td><code>Observed 412 times over the last 30 runs, always 200</code></td></tr><tr><td><strong>Declared, never hit</strong></td><td>blind-spot</td><td>a route or page the application declares that no test reaches</td><td>a <a href="/features/scenario-gaps.html#declared-surface">declared surface</a></td><td><code>Declared in OpenAPI · 0 tests in 30 runs · documents 200, 404</code></td></tr><tr><td><strong>Surface drift</strong></td><td>blind-spot</td><td>a route or page first seen in the latest run</td><td>nothing more</td><td><code>Appeared in run #830, reached by 1 test(s) so far</code></td></tr><tr><td><strong>Control nobody exercises</strong></td><td>blind-spot</td><td>a control on a page that no test reaches</td><td>the page inventory</td><td><code>On 12 page(s) · no locator targets it</code></td></tr><tr><td><strong>Reachable, unvisited</strong></td><td>blind-spot</td><td>a page other pages link to that no test navigates to</td><td>the page inventory</td><td><code>Linked from 7 page(s) · never navigated to</code></td></tr><tr><td><strong>API-only route</strong></td><td>blind-spot</td><td>a reached route no page loads</td><td>the page inventory; without it, every reached route qualifies</td><td><code>No control triggers it and no page loads it</code></td></tr><tr><td><strong>Escaped defect</strong></td><td>blind-spot</td><td>a page with <a href="/features/bug-reports.html">bug reports</a> no test names yet, one gap per page</td><td>Piwi Picker sending reports</td><td><code>Bug report #37: Coupon not applied to the total — no test names it yet</code></td></tr><tr><td><strong>Changed, unreached</strong></td><td>blind-spot</td><td>a changed file no test reaches, at pull-request time</td><td>an SCM token</td><td><code>+41 −3 · no test in run #812 · 0 in 30 runs</code></td></tr><tr><td><strong>Single covering test</strong></td><td>fragile</td><td>a node exactly one trusted test reaches</td><td>nothing more</td><td><code>Only checkout › coupon reaches this</code></td></tr><tr><td><strong>Orphan test</strong></td><td>fragile</td><td>a test whose every reached node disappeared from the last 30 runs</td><td>nothing more</td><td><code>All 3 node(s) it reaches disappeared from recent runs</code></td></tr><tr><td><strong>Fix did not hold</strong></td><td>fragile</td><td>a failure cluster whose fix later regressed</td><td>nothing more</td><td><code>Fixed in a1b2c3d · regressed 6 days later</code></td></tr><tr><td><strong>Not noticed</strong></td><td>false-comfort</td><td>a route a probe broke while no test noticed</td><td><a href="/features/probes.html">probes</a></td><td><code>A probe (status-500) on POST /api/orders did not make checkout › pay fail</code></td></tr><tr><td><strong>Unprobed dependency</strong></td><td>false-comfort</td><td>a dependency a route&#39;s handler calls that no probe has failed</td><td>server spans</td><td><code>Called by 4 route(s) · no probe has checked what happens when it fails</code></td></tr><tr><td><strong>Not handled</strong></td><td>unhandled, degraded</td><td>the application did not cope with a server probe&#39;s fault; a finding, not a gap</td><td><a href="/features/probes.html#server-probes">server probes</a></td><td><code>A server probe made POST /api/orders fail; the application did not handle it</code></td></tr></tbody></table><p>A trusted test is one that is not flaky, not quarantined, and not skipped in its latest run. <em>Changed, unreached</em> is covered on <a href="/features/uncovered-changes.html">Uncovered changes in pull requests</a>. A finding never closes itself; triage it.</p><p>A test reaches a control only through triage (<em>covered by</em> or <em>covered elsewhere</em>): runs record reach to routes and pages. So <em>Control nobody exercises</em> reports a control only once some control on the project has a covering test.</p><h2 id="exposure" tabindex="-1">Exposure <a class="header-anchor" href="#exposure" aria-label="Permalink to &quot;Exposure&quot;">​</a></h2><p>A gap&#39;s score is its detector&#39;s confidence times its <strong>exposure</strong>, the geometric mean of four factors. Each factor is kept between 0.1 and 1, so a missing input lowers the score without zeroing it.</p><table tabindex="0"><thead><tr><th>Factor</th><th>From</th><th>Reaches 1 at</th></tr></thead><tbody><tr><td><strong>Churn</strong></td><td>commits touching the files in the last 90 days</td><td>12 commits</td></tr><tr><td><strong>Age</strong></td><td>the age of those files; older weighs more, since escaped defects concentrate there</td><td>one year</td></tr><tr><td><strong>Escape history</strong></td><td>whether a file was part of a failure cluster&#39;s fixing commit</td><td>yes, else 0.1</td></tr><tr><td><strong>Priority</strong></td><td>the highest <a href="/reference/test-metadata.html#ownership-metadata-piwi-annotations"><code>piwi:priority</code></a> of the tests reaching the node: critical 1, high 0.7, medium 0.4, low 0.2</td><td>critical</td></tr></tbody></table><p>Churn, age and escape history come from the <a href="/guide/source-control.html">source control</a> connection and apply to the files a pull request changed; the other detectors rank by priority and confidence. A finding ranks by its severity (1 for unhandled, 0.5 for degraded) times the route&#39;s reach.</p><h2 id="what-the-graph-includes" tabindex="-1">What the graph includes <a class="header-anchor" href="#what-the-graph-includes" aria-label="Permalink to &quot;What the graph includes&quot;">​</a></h2><p>The graph stays proportional to the application&#39;s surface, not its data volume:</p><ul><li><strong>Your own origin only.</strong> Route nodes come from requests to the Playwright <code>baseURL</code> of the run&#39;s projects (or the project&#39;s configured route origins); analytics beacons and CDN assets never become nodes.</li><li><strong>Pages are path patterns.</strong> <code>/orders/123</code> and <code>/orders/456</code> are one node, as is the same path from staging and production.</li><li><strong>Controls and links are templated.</strong> Dates, ids and numbers in an accessible name become placeholders, and each page keeps at most 200 controls and 200 links.</li><li><strong>Branches stay separate.</strong> A default-branch run writes the canonical graph; any other branch writes rows tagged with it, so a route added on a pull request never shows as drift on the default branch. Those rows drop when the pull request closes, or after 30 days unseen. Detectors read the canonical graph; change coverage reads every branch.</li><li><strong>Old nodes retire.</strong> A node unseen for 30 default-branch runs that backs no open gap leaves the graph.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/scenario-gaps.html">Scenario gaps &amp; the Test Map</a>: the Gaps tab and triage</li><li><a href="/features/probes.html">Probes</a>: the source of the false-comfort and resilience classes</li><li><a href="/guide/concepts.html#test-map">Core concepts</a>: the Test Map vocabulary</li></ul>',16)])])}const u=t(s,[["render",d]]);export{g as __pageData,u as default};
